css:
:root{
  --navy:#002c34; --navy-2:#053c46; --navy-3:#00212a;
  --teal:#017994; --teal-2:#0a94b0; --teal-050:#e6f1f4; --teal-100:#cfe6ec;
  --gold:#f0b429; --gold-2:#f7c74c; --gold-d:#cf9410;
  --ink:#0f2a31; --body:#4c5c63; --muted:#88979e;
  --mist:#eef4f6; --mist-2:#f6fafb; --line:#dde8ea; --line-2:#e9f0f2; --line-ink:rgba(255,255,255,.14);
  --white:#fff;
  --max:1240px; --gut:40px;
  --disp:"Plus Jakarta Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;
  --f:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --shadow:0 12px 34px rgba(0,44,52,.10); --shadow-lg:0 30px 70px rgba(0,44,52,.16);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--f);color:var(--body);background:var(--white);line-height:1.7;-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{text-decoration:none;color:inherit}
img{max-width:100%;display:block}
h1,h2,h3,h4{margin:0;color:var(--ink);font-family:var(--disp);font-weight:700;line-height:1.1;letter-spacing:-.02em}
p{margin:0}
.wrap{max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
@media(max-width:768px){:root{--gut:26px}}
@media(max-width:430px){:root{--gut:20px}}
.ic{width:1em;height:1em;flex:none;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.eyebrow{display:inline-flex;align-items:center;gap:10px;font-size:.76rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--teal)}
.eyebrow.on-dark{color:var(--gold-2)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;font-family:var(--f);font-weight:700;font-size:.92rem;letter-spacing:.01em;padding:15px 28px;border-radius:40px;cursor:pointer;border:2px solid transparent;transition:.2s;white-space:nowrap}
.btn .ic{width:17px;height:17px;stroke-width:2.4}
.btn-gold{background:var(--gold);color:var(--navy);box-shadow:0 10px 24px rgba(240,180,41,.36)}
.btn-gold:hover{background:var(--gold-2);transform:translateY(-2px)}
.btn-navy{background:var(--navy);color:#fff}
.btn-navy:hover{background:var(--navy-2);transform:translateY(-2px)}
.btn-teal{background:var(--teal);color:#fff}
.btn-teal:hover{background:var(--teal-2);transform:translateY(-2px)}
.btn-ghost{background:transparent;color:var(--navy);border-color:var(--line)}
.btn-ghost:hover{border-color:var(--navy);transform:translateY(-2px)}
.btn-ghost-lt{background:rgba(255,255,255,.06);color:#fff;border-color:rgba(255,255,255,.4)}
.btn-ghost-lt:hover{background:#fff;color:var(--navy);border-color:#fff}
.section{padding:96px 0;position:relative}
.sec-head{max-width:720px;margin:0 auto 54px;text-align:center}
.sec-head h2{font-size:clamp(1.9rem,3.6vw,2.7rem)}
.sec-head h2 em{font-style:normal;color:var(--teal)}
.sec-head p{margin-top:15px;font-size:1.06rem;color:var(--body)}
.tag{display:inline-block;background:var(--teal-050);color:var(--teal);border:1px solid var(--teal-100);border-radius:20px;font-size:.72rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:5px 12px}
.ph{background:var(--mist);display:block;width:100%;height:100%;object-fit:cover}

/* reveal (nifty-safe: always visible; entrance only) */
.rv{animation:rvIn .7s cubic-bezier(.2,.7,.2,1) both}
.rv.d1{animation-delay:.08s}.rv.d2{animation-delay:.16s}.rv.d3{animation-delay:.24s}.rv.d4{animation-delay:.32s}
@keyframes rvIn{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.rv{animation:none}}

/* ============ UTILITY BAR ============ */
.util{background:var(--navy);color:#c7d6da;font-size:.82rem}
.util .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:44px}
.util .u-l{display:flex;gap:24px;align-items:center}
.util .u-l a,.util .u-l span{display:inline-flex;align-items:center;gap:8px}
.util a:hover{color:#fff}
.util .ic{width:15px;height:15px;color:var(--gold-2)}
.util strong{color:#fff;font-weight:700}
.util .u-r{display:flex;gap:20px;align-items:center}
.util .cred{display:inline-flex;align-items:center;gap:8px;color:#9fb6bc}
@media(max-width:900px){.util .u-r{display:none}}
@media(max-width:560px){.util .u-l{gap:14px}.util .u-l .hide-xs{display:none}}

/* ============ HEADER ============ */
.hdr{position:sticky;top:0;z-index:70;background:rgba(255,255,255,.96);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.hdr-in{display:flex;align-items:center;gap:16px;min-height:82px}
.brand{flex:none;display:flex;align-items:center}
.brand img{height:52px;width:auto;display:block}
.nav-cb{display:none}
.nav{margin-left:auto;display:flex;align-items:center;gap:20px}
.nav-links{display:flex;align-items:center;gap:1px;list-style:none;margin:0;padding:0}
.nav-links>li>a{display:flex;align-items:center;gap:5px;padding:9px 9px;font-family:var(--f);font-size:.82rem;font-weight:600;color:var(--ink);border-radius:8px;letter-spacing:0;white-space:nowrap}
.nav-links>li>a:hover{color:var(--teal);background:var(--teal-050)}
.nav-links>li.active>a{color:var(--teal)}
.nav-links .caret{width:13px;height:13px;stroke-width:2.4}
.has-drop{position:relative}
.has-drop .drop-cb{display:none}
.dropdown{position:absolute;top:calc(100% + 6px);left:0;min-width:250px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow-lg);padding:8px;opacity:0;visibility:hidden;transition:.15s;z-index:80}
.has-drop:hover .dropdown{opacity:1;visibility:visible;top:calc(100% + 2px)}
.dropdown a{display:flex;align-items:center;gap:10px;padding:11px 13px;border-radius:9px;font-family:var(--f);font-size:.86rem;font-weight:600;color:var(--ink)}
.dropdown a:hover{background:var(--teal-050);color:var(--teal)}
.dropdown a .dot{width:7px;height:7px;border-radius:50%;background:var(--gold);flex:none}
.hdr-cta{display:flex;align-items:center;gap:13px;flex:none}
.hdr-phone{display:inline-flex;flex-direction:column;line-height:1.1;text-align:right}
.hdr-phone small{font-size:.64rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:700}
.hdr-phone b{font-size:1.02rem;color:var(--navy);font-family:var(--disp);font-weight:800}
.burger{display:none;margin-left:auto;width:48px;height:48px;border:1px solid var(--line);border-radius:11px;cursor:pointer;align-items:center;justify-content:center;color:var(--navy);background:#fff}
.burger svg{width:24px;height:24px;stroke-width:2}
.burger .x{display:none}
.nav-cb:checked ~ .burger .menu{display:none}.nav-cb:checked ~ .burger .x{display:block}
@media(max-width:1360px){
  .burger{display:flex}
  .nav{position:fixed;inset:0 0 0 auto;top:0;height:100vh;width:min(360px,88vw);margin:0;background:#fff;flex-direction:column;align-items:stretch;gap:0;padding:26px 0 30px;box-shadow:var(--shadow-lg);clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .32s ease;overflow-y:auto;z-index:90}
  .nav-cb:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
  .nav-links{flex-direction:column;align-items:stretch;gap:0;width:100%}
  .nav-links>li>a{justify-content:space-between;padding:16px 26px;border-bottom:1px solid var(--line-2);border-radius:0;font-size:.98rem}
  .nav-links>li.has-drop>a{display:none}
  .dropdown{position:static;opacity:1;visibility:visible;box-shadow:none;border:0;border-radius:0;min-width:0;padding:0;max-height:0;overflow:hidden;transition:max-height .3s ease;background:var(--mist-2)}
  .drop-cb:checked ~ .dropdown{max-height:420px}
  .drop-lbl{display:flex!important;align-items:center;justify-content:space-between;padding:16px 26px;border-bottom:1px solid var(--line-2);font-family:var(--f);font-weight:600;font-size:.98rem;color:var(--ink);cursor:pointer}
  .drop-cb:checked ~ .drop-lbl .caret{transform:rotate(180deg)}
  .drop-lbl .caret{transition:.25s;width:15px;height:15px}
  .dropdown a{padding:14px 34px}
  .hdr-cta{display:none}
  .nav .m-cta{display:flex;flex-direction:column;gap:12px;padding:22px 26px 0}
  .nav .m-cta .btn{width:100%}
}
@media(min-width:1361px){.drop-lbl{display:none}.nav .m-cta{display:none}}
.scrim{display:none}
@media(max-width:1360px){.nav-cb:checked ~ .scrim{display:block;position:fixed;inset:0;background:rgba(0,20,26,.5);z-index:85}}

/* ============ HERO ============ */
.hero{position:relative;overflow:hidden;background:radial-gradient(1100px 620px at 88% -6%,var(--teal-050),transparent 62%),linear-gradient(180deg,var(--mist-2),var(--white) 70%)}
.hero::before{content:"";position:absolute;top:-140px;right:-120px;width:520px;height:520px;border-radius:50%;background:radial-gradient(circle,rgba(1,121,148,.10),transparent 68%);pointer-events:none}
.hero-grid{position:relative;z-index:2;display:grid;grid-template-columns:1.08fr .92fr;gap:56px;align-items:center;padding-top:70px;padding-bottom:84px}
.hero-pill{display:inline-flex;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:40px;padding:8px 16px 8px 8px;font-size:.8rem;font-weight:600;color:var(--ink);box-shadow:var(--shadow)}
.hero-pill .p-ic{width:26px;height:26px;border-radius:50%;background:var(--teal);color:#fff;display:grid;place-items:center;flex:none}
.hero-pill .p-ic .ic{width:15px;height:15px;stroke-width:2.6}
.hero-pill b{color:var(--teal);font-weight:700}
.hero h1{margin-top:22px;font-size:clamp(2.5rem,5.4vw,4.2rem);line-height:1.02;font-weight:800;color:var(--navy);letter-spacing:-.03em}
.hero h1 em{font-style:normal;color:var(--teal);position:relative;white-space:nowrap}
.hero h1 em::after{content:"";position:absolute;left:0;right:0;bottom:.06em;height:.14em;background:var(--gold);opacity:.5;border-radius:3px;z-index:-1}
.hero .lead{margin-top:22px;font-size:1.14rem;color:var(--body);max-width:42ch}
.hero-chips{display:flex;flex-wrap:wrap;gap:9px;margin-top:24px}
.hero-chips span{background:#fff;border:1px solid var(--line);border-radius:30px;padding:8px 15px;font-size:.82rem;font-weight:600;color:var(--navy)}
.hero-chips span b{color:var(--teal)}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-top:30px}
.hero-trust{display:flex;flex-wrap:wrap;gap:10px 22px;margin-top:28px}
.hero-trust span{display:inline-flex;align-items:center;gap:8px;font-size:.9rem;font-weight:600;color:var(--navy)}
.hero-trust .ic{width:20px;height:20px;color:#fff;background:var(--teal);border-radius:50%;padding:4px;stroke-width:3}
/* hero visual */
.hero-visual{position:relative}
.hv-photo{border-radius:22px;overflow:hidden;aspect-ratio:4/5;box-shadow:var(--shadow-lg);position:relative}
.hv-photo::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(0,44,52,.18))}
.hv-card{position:absolute;background:#fff;border-radius:16px;box-shadow:var(--shadow-lg);padding:16px 18px}
.hv-card.dash{left:-30px;top:40px;width:230px}
.hv-card.dash .dh{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
.hv-card.dash .dh small{font-size:.66rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:700}
.hv-card.dash .dh .dot{width:9px;height:9px;border-radius:50%;background:var(--teal)}
.hv-card.dash .amt{font-family:var(--disp);font-weight:800;font-size:1.5rem;color:var(--navy)}
.hv-card.dash .amt span{color:var(--teal)}
.hv-card.dash .sub{font-size:.72rem;color:var(--muted);margin-top:2px}
.hv-card.dash .bars{display:flex;align-items:flex-end;gap:6px;height:46px;margin-top:12px}
.hv-card.dash .bars i{flex:1;background:var(--teal-100);border-radius:3px 3px 0 0}
.hv-card.dash .bars i.on{background:var(--teal)}
.hv-card.badge{right:-24px;bottom:60px;display:flex;align-items:center;gap:12px;width:auto}
.hv-card.badge .b-ic{width:42px;height:42px;border-radius:11px;background:var(--gold);color:var(--navy);display:grid;place-items:center;flex:none}
.hv-card.badge b{display:block;font-family:var(--disp);font-weight:800;color:var(--navy);font-size:.98rem;line-height:1.1}
.hv-card.badge small{font-size:.72rem;color:var(--muted)}
.hv-chat{position:absolute;right:-10px;top:-18px;background:var(--navy);color:#dbe9ec;font-size:.78rem;padding:12px 15px;border-radius:14px 14px 14px 3px;max-width:210px;box-shadow:var(--shadow-lg);z-index:3}
.hv-chat b{color:#fff}
@media(max-width:960px){.hero-grid{grid-template-columns:1fr;gap:44px;padding-top:44px;padding-bottom:60px}.hero .lead{max-width:none}.hv-card.dash{left:0}.hv-card.badge{right:0}.hv-chat{display:none}}
@media(max-width:520px){.hv-card.dash{width:190px}.hv-chat{display:none}}

/* ============ ACCREDITATIONS ============ */
.accred{background:#fff;border-bottom:1px solid var(--line)}
.accred .wrap{padding:30px 24px}
.accred .lbl{text-align:center;font-size:.74rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:20px}
.accred .row{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:16px 34px}
.accred .a{display:inline-flex;align-items:center;gap:9px;font-family:var(--disp);font-weight:700;color:#5c6d74;font-size:1rem;letter-spacing:.01em}
.accred .a .ic{width:20px;height:20px;color:var(--teal)}
.accred .a small{display:block;font-family:var(--f);font-weight:600;font-size:.62rem;color:var(--muted);letter-spacing:.04em}
.accred .a-img{display:inline-flex;align-items:center}
.accred .a-img img{height:42px;width:auto;display:block}
.accred .row{gap:18px 30px}
@media(max-width:560px){.accred .a-img img{height:34px}}

/* ============ PILLARS ============ */
.pillars{background:var(--mist)}
.pillar-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}
.pillar{background:#fff;border:1px solid var(--line);border-radius:20px;padding:34px 30px 30px;transition:.24s;position:relative;overflow:hidden}
.pillar::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,var(--teal),var(--teal-2));transform:scaleX(0);transform-origin:left;transition:.3s}
.pillar:hover{transform:translateY(-8px);box-shadow:var(--shadow-lg);border-color:transparent}
.pillar:hover::before{transform:scaleX(1)}
.pillar .pi{width:62px;height:62px;border-radius:16px;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;margin-bottom:20px}
.pillar .pi .ic{width:30px;height:30px}
.pillar h3{font-size:1.32rem;letter-spacing:-.01em}
.pillar p{margin-top:12px;font-size:.97rem;color:var(--body)}
.pillar .more{display:inline-flex;align-items:center;gap:8px;margin-top:20px;font-weight:700;font-size:.86rem;color:var(--teal)}
.pillar:hover .more .ic{transform:translateX(4px)}
.pillar .more .ic{width:16px;height:16px;stroke-width:2.6;transition:.2s}
@media(max-width:900px){.pillar-grid{grid-template-columns:1fr}}

/* ============ ABOUT ============ */
.about-grid{display:grid;grid-template-columns:.95fr 1.05fr;gap:66px;align-items:center}
.about-fig{position:relative}
.about-fig .imgwrap{border-radius:22px;overflow:hidden;aspect-ratio:5/6;box-shadow:var(--shadow)}
.about-fig .imgwrap img{width:100%;height:100%;object-fit:cover}
.about-fig .stat{position:absolute;right:-22px;bottom:34px;background:var(--navy);color:#fff;border-radius:16px;padding:20px 24px;box-shadow:var(--shadow-lg);text-align:center}
.about-fig .stat b{font-family:var(--disp);font-weight:800;font-size:2rem;display:block;line-height:1}
.about-fig .stat b span{color:var(--gold-2)}
.about-fig .stat small{font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;color:#a9c1c6}
.about-copy h2{font-size:clamp(1.9rem,3.6vw,2.7rem)}
.about-copy h2 em{font-style:normal;color:var(--teal)}
.about-copy p{margin-top:18px;font-size:1.04rem;color:var(--body)}
.about-points{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:26px}
.about-points li{list-style:none;display:flex;gap:11px;font-size:.95rem;font-weight:600;color:var(--navy)}
.about-points .ic{width:22px;height:22px;color:#fff;background:var(--teal);border-radius:50%;padding:4px;flex:none;stroke-width:3}
.about-copy .btn{margin-top:28px}
@media(max-width:900px){.about-grid{grid-template-columns:1fr;gap:44px}.about-fig{order:-1}.about-points{grid-template-columns:1fr}.about-fig .stat{right:8px;bottom:16px}}

/* ============ SERVICES ============ */
.svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.svc{background:#fff;border:1px solid var(--line);border-radius:16px;padding:24px 22px;transition:.2s;display:block}
.svc:hover{border-color:var(--teal);box-shadow:var(--shadow);transform:translateY(-4px)}
.svc .si{width:46px;height:46px;border-radius:12px;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;margin-bottom:15px}
.svc .si .ic{width:23px;height:23px}
.svc h3{font-size:1.02rem;letter-spacing:-.01em}
.svc p{margin-top:7px;font-size:.86rem;color:var(--muted)}
@media(max-width:900px){.svc-grid{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.svc-grid{grid-template-columns:1fr}}

/* ============ INDUSTRIES ============ */
.industries{background:var(--navy);color:#fff;position:relative;overflow:hidden}
.industries::before{content:"";position:absolute;top:-120px;left:-100px;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle,rgba(1,121,148,.4),transparent 66%)}
.industries .sec-head h2{color:#fff}.industries .sec-head p{color:#bcd2d7}.industries .eyebrow{color:var(--gold-2)}
.ind-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;position:relative;z-index:1}
.ind{display:flex;align-items:center;gap:14px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:18px 20px;transition:.2s}
.ind:hover{background:rgba(255,255,255,.1);border-color:var(--gold)}
.ind .ii{width:44px;height:44px;border-radius:11px;background:rgba(240,180,41,.16);color:var(--gold-2);display:grid;place-items:center;flex:none}
.ind .ii .ic{width:22px;height:22px}
.ind b{font-family:var(--disp);font-weight:700;color:#fff;font-size:1rem}
@media(max-width:820px){.ind-grid{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.ind-grid{grid-template-columns:1fr}}

/* ============ WHY ============ */
.why-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.why{text-align:left}
.why .wi{width:56px;height:56px;border-radius:15px;background:var(--teal);color:#fff;display:grid;place-items:center;margin-bottom:16px}
.why .wi .ic{width:27px;height:27px}
.why h3{font-size:1.1rem}
.why p{margin-top:9px;font-size:.92rem}
@media(max-width:900px){.why-grid{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.why-grid{grid-template-columns:1fr}}

/* ============ TESTIMONIAL ============ */
.testi{background:var(--teal-050)}
.testi-card{max-width:900px;margin:0 auto;background:#fff;border-radius:24px;box-shadow:var(--shadow);padding:52px 54px;text-align:center;position:relative;overflow:hidden}
.testi-card::before{content:"\201C";position:absolute;top:-10px;left:34px;font-family:Georgia,serif;font-size:9rem;color:var(--teal);opacity:.12;line-height:1}
.testi-card .stars{display:inline-flex;gap:5px;color:var(--gold);margin-bottom:20px}
.testi-card .stars .ic{width:22px;height:22px;fill:currentColor;stroke:none}
.testi-card blockquote{margin:0;font-family:var(--disp);font-weight:600;font-size:clamp(1.2rem,2.4vw,1.7rem);line-height:1.45;color:var(--ink);letter-spacing:-.01em}
.testi-card .by{margin-top:26px;display:inline-flex;align-items:center;gap:14px}
.testi-card .by .av{width:52px;height:52px;border-radius:50%;background:var(--navy);color:#fff;display:grid;place-items:center;font-family:var(--disp);font-weight:800;font-size:1.1rem}
.testi-card .by .n{text-align:left}
.testi-card .by .n b{display:block;font-family:var(--disp);color:var(--ink);font-size:1.02rem}
.testi-card .by .n small{color:var(--muted);font-size:.86rem}
@media(max-width:560px){.testi-card{padding:40px 26px}}

/* ============ FAQ ============ */
.faq-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:56px;align-items:start}
.faq-intro{position:sticky;top:110px}
.faq-intro h2{font-size:clamp(1.9rem,3.6vw,2.6rem)}
.faq-intro h2 em{font-style:normal;color:var(--teal)}
.faq-intro p{margin-top:14px;font-size:1.04rem;color:var(--body)}
.faq-intro .btn{margin-top:24px}
.faq-list{display:grid;gap:12px}
.faq{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;transition:.2s}
.faq[open]{border-color:var(--teal);box-shadow:var(--shadow)}
.faq summary{list-style:none;cursor:pointer;padding:20px 22px;display:flex;align-items:center;justify-content:space-between;gap:16px;font-family:var(--disp);font-weight:700;color:var(--ink);font-size:1.04rem}
.faq summary::-webkit-details-marker{display:none}
.faq summary .pl{width:28px;height:28px;flex:none;border-radius:50%;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;transition:.2s}
.faq[open] summary .pl{transform:rotate(45deg);background:var(--teal);color:#fff}
.faq .pl .ic{width:16px;height:16px;stroke-width:3}
.faq .fa{padding:0 22px 22px;color:var(--body);font-size:.98rem}
@media(max-width:900px){.faq-grid{grid-template-columns:1fr;gap:34px}.faq-intro{position:static}}

/* ============ OFFICES ============ */
.offices{background:var(--mist)}
.office-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.office{background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden;transition:.2s}
.office:hover{box-shadow:var(--shadow);transform:translateY(-4px)}
.office .omap{aspect-ratio:16/10;position:relative}
.office .obody{padding:22px 24px 24px}
.office .otag{font-size:.72rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--teal)}
.office h3{font-size:1.16rem;margin-top:6px}
.office p{margin-top:8px;font-size:.94rem;color:var(--body)}
@media(max-width:820px){.office-grid{grid-template-columns:1fr}}

/* ============ CTA BAND ============ */
.ctaband{background:linear-gradient(120deg,var(--navy),var(--navy-2));color:#fff;position:relative;overflow:hidden}
.ctaband::before{content:"";position:absolute;top:-140px;right:-80px;width:460px;height:460px;border-radius:50%;background:radial-gradient(circle,rgba(1,121,148,.5),transparent 66%)}
.ctaband::after{content:"";position:absolute;bottom:-160px;left:-60px;width:380px;height:380px;border-radius:50%;background:radial-gradient(circle,rgba(240,180,41,.16),transparent 66%)}
.ctaband .wrap{position:relative;z-index:1;text-align:center;padding:76px 24px}
.ctaband .eyebrow{color:var(--gold-2)}
.ctaband h2{color:#fff;font-size:clamp(2rem,4.4vw,3.1rem);margin-top:16px;letter-spacing:-.02em}
.ctaband p{color:#c7dbe0;font-size:1.14rem;margin-top:16px}
.ctaband .cta-actions{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;margin-top:32px}
.ctaband .phone-lg{margin-top:24px;font-family:var(--disp);font-weight:800;font-size:1.3rem;color:#fff;display:inline-flex;align-items:center;gap:10px}
.ctaband .phone-lg .ic{color:var(--gold-2)}

/* ============ FOOTER ============ */
.foot-badges{display:flex;align-items:center;justify-content:center;gap:20px 30px;flex-wrap:wrap;padding-bottom:40px;margin-bottom:44px;border-bottom:1px solid var(--line-ink)}
.foot-badges .fb-label{font-family:var(--f);font-size:.72rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:rgba(255,255,255,.55)}
.foot-badges .fb-row{display:flex;gap:14px;flex-wrap:wrap;align-items:center;justify-content:center}
.foot-badges .fb{background:#fff;border-radius:12px;padding:9px 16px;display:flex;align-items:center;justify-content:center;height:58px;box-shadow:0 6px 16px rgba(0,0,0,.18)}
.foot-badges .fb img{height:36px;width:auto;display:block}
@media(max-width:560px){.foot-badges{flex-direction:column;gap:16px}.foot-badges .fb{height:52px}.foot-badges .fb img{height:32px}}

footer.site{background:var(--navy-3);color:rgba(255,255,255,.62);padding:72px 0 28px}
.foot-top{display:grid;grid-template-columns:1.7fr 1fr 1fr 1fr;gap:44px;padding-bottom:44px;border-bottom:1px solid var(--line-ink)}
.foot-brand img{height:60px;width:auto;margin-bottom:20px}
.foot-brand p{font-size:.94rem;color:rgba(255,255,255,.55);max-width:36ch}
.foot-brand .fc{margin-top:20px;display:grid;gap:11px}
.foot-brand .fc a,.foot-brand .fc span{display:flex;align-items:flex-start;gap:11px;font-size:.94rem;color:#e6eef0}
.foot-brand .fc .ic{width:17px;height:17px;color:var(--gold-2);flex:none;margin-top:3px}
footer.site h4{color:#fff;font-family:var(--f);font-size:.74rem;letter-spacing:.16em;text-transform:uppercase;font-weight:700;margin:0 0 20px}
footer.site .fcol ul{list-style:none;margin:0;padding:0;display:grid;gap:12px}
footer.site .fcol a{font-size:.93rem;color:rgba(255,255,255,.6)}
footer.site .fcol a:hover{color:var(--gold-2)}
.foot-bottom{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-top:26px;font-size:.82rem;color:rgba(255,255,255,.42)}
.foot-bottom .legal{display:flex;gap:20px;flex-wrap:wrap}
.foot-credit{text-align:center;margin-top:16px;padding-top:16px;border-top:1px solid var(--line-ink);font-size:.8rem;color:rgba(255,255,255,.4)}
@media(max-width:960px){.foot-top{grid-template-columns:1fr 1fr;gap:34px}.foot-brand{grid-column:1/-1}}
@media(max-width:560px){.foot-top{grid-template-columns:1fr}.foot-bottom{flex-direction:column;text-align:center;justify-content:center}.foot-bottom .legal{justify-content:center}}

/* sticky mobile CTA */
.mcta{display:none}
@media(max-width:720px){
  .mcta{display:grid;grid-template-columns:1fr 1fr;position:fixed;left:0;right:0;bottom:0;z-index:95;box-shadow:0 -6px 20px rgba(0,0,0,.12)}
  .mcta a{padding:15px;text-align:center;font-family:var(--f);font-weight:700;font-size:.86rem;display:flex;align-items:center;justify-content:center;gap:8px}
  .mcta .c1{background:var(--gold);color:var(--navy)}.mcta .c2{background:var(--navy);color:#fff}
  .mcta .ic{width:16px;height:16px}
  body{padding-bottom:52px}
}
.demonote{display:none}

/* ============ PAGE HERO (interior) ============ */
.phero{position:relative;overflow:hidden;background:radial-gradient(1100px 620px at 88% -6%,var(--teal-050),transparent 62%),linear-gradient(180deg,var(--mist-2),var(--white) 78%)}
.phero::before{content:"";position:absolute;top:-150px;right:-120px;width:520px;height:520px;border-radius:50%;background:radial-gradient(circle,rgba(1,121,148,.10),transparent 68%);pointer-events:none}
.phero-in{position:relative;z-index:2;padding-top:60px;padding-bottom:62px}
.crumbs{display:flex;flex-wrap:wrap;align-items:center;gap:9px;font-size:.84rem;font-weight:600;color:var(--muted)}
.crumbs a{color:var(--teal)}
.crumbs a:hover{text-decoration:underline}
.crumbs .ic{width:13px;height:13px;color:var(--muted)}
.crumbs span[aria-current]{color:var(--navy)}
.phero .hero-pill{margin-top:20px}
.phero h1{margin-top:20px;font-size:clamp(2.3rem,5vw,3.6rem);line-height:1.03;font-weight:800;color:var(--navy);letter-spacing:-.03em}
.phero h1 em{font-style:normal;color:var(--teal);position:relative;white-space:nowrap}
.phero h1 em::after{content:"";position:absolute;left:0;right:0;bottom:.06em;height:.14em;background:var(--gold);opacity:.5;border-radius:3px;z-index:-1}
.phero .lead{margin-top:20px;font-size:1.12rem;color:var(--body);max-width:60ch}
.phero .hero-cta{margin-top:28px}
@media(max-width:768px){.phero-in{padding-top:40px;padding-bottom:46px}}

/* ============ IMPORTANT LINK CARDS ============ */
.link-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.lcard{background:#fff;border:1px solid var(--line);border-radius:20px;padding:34px 30px 30px;display:flex;flex-direction:column;position:relative;overflow:hidden;transition:.24s}
.lcard::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,var(--teal),var(--teal-2));transform:scaleX(0);transform-origin:left;transition:.3s}
.lcard:hover{transform:translateY(-8px);box-shadow:var(--shadow-lg);border-color:transparent}
.lcard:hover::before{transform:scaleX(1)}
.lcard .li{width:62px;height:62px;border-radius:16px;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;margin-bottom:20px}
.lcard .li .ic{width:30px;height:30px}
.lcard h2{font-size:1.34rem;letter-spacing:-.01em}
.lcard p{margin-top:12px;font-size:.97rem;color:var(--body);flex:1}
.lcard .btn{margin-top:22px;align-self:flex-start}
.lcard .ext{margin-top:14px;display:inline-flex;align-items:center;gap:7px;font-size:.76rem;font-weight:600;color:var(--muted)}
.lcard .ext .ic{width:14px;height:14px}
@media(max-width:900px){.link-grid{grid-template-columns:1fr}}

/* ============ NOTE STRIP ============ */
.notestrip{background:var(--teal-050);border:1px solid var(--teal-100);border-radius:18px;display:flex;gap:18px;align-items:flex-start;padding:26px 28px;margin-top:34px}
.notestrip .ni{width:44px;height:44px;border-radius:12px;background:var(--teal);color:#fff;display:grid;place-items:center;flex:none}
.notestrip .ni .ic{width:22px;height:22px}
.notestrip b{display:block;font-family:var(--disp);color:var(--ink);font-size:1.04rem;margin-bottom:6px}
.notestrip p{font-size:.95rem;color:var(--body)}
@media(max-width:560px){.notestrip{flex-direction:column;gap:14px;padding:24px}}

/* ============ TESTIMONIAL GRID ============ */
.tgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.tc{background:#fff;border:1px solid var(--line);border-radius:18px;padding:28px 26px;display:flex;flex-direction:column;transition:.2s}
.tc:hover{box-shadow:var(--shadow);transform:translateY(-4px)}
.tc .stars{display:inline-flex;gap:4px;color:var(--gold);margin-bottom:16px}
.tc .stars .ic{width:17px;height:17px;fill:currentColor;stroke:none}
.tc blockquote{margin:0;font-size:.96rem;line-height:1.62;color:var(--ink);flex:1}
.tc .by{margin-top:22px;display:flex;align-items:center;gap:12px}
.tc .by .av{width:44px;height:44px;border-radius:50%;background:var(--navy);color:#fff;display:grid;place-items:center;font-family:var(--disp);font-weight:800;font-size:.92rem;flex:none}
.tc .by b{display:block;font-family:var(--disp);color:var(--ink);font-size:.96rem}
.tc .by small{color:var(--muted);font-size:.82rem}
@media(max-width:1040px){.tgrid{grid-template-columns:1fr 1fr}}
@media(max-width:600px){.tgrid{grid-template-columns:1fr}}

/* ============ GOOGLE REVIEWS ============ */
.revs{background:var(--mist)}
.rgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;align-items:start}
.rc{background:#fff;border:1px solid var(--line);border-radius:16px;padding:24px 24px 26px}
.rc .rh{display:flex;align-items:center;gap:12px;margin-bottom:14px}
.rc .rav{width:40px;height:40px;border-radius:50%;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;font-family:var(--disp);font-weight:800;font-size:.86rem;flex:none}
.rc .rn b{display:block;font-family:var(--disp);color:var(--ink);font-size:.95rem;line-height:1.2}
.rc .rn .src{display:inline-flex;align-items:center;gap:6px;font-size:.72rem;font-weight:600;color:var(--muted);margin-top:3px}
.rc .rn .src .ic{width:13px;height:13px;color:var(--teal)}
.rc .stars{display:inline-flex;gap:3px;color:var(--gold);margin-bottom:10px}
.rc .stars .ic{width:15px;height:15px;fill:currentColor;stroke:none}
.rc p{font-size:.92rem;line-height:1.62;color:var(--body)}
@media(max-width:980px){.rgrid{grid-template-columns:1fr 1fr}}
@media(max-width:620px){.rgrid{grid-template-columns:1fr}}

/* ============ PAGE HERO: two-column with quick-links card ============ */
.phero-in{display:grid;grid-template-columns:1.06fr .94fr;gap:56px;align-items:center}
.phero-copy{min-width:0}
.qcard{background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow-lg);padding:28px 28px 24px;position:relative;min-width:0}
.qcard .qh{display:flex;align-items:center;gap:12px;padding-bottom:18px;margin-bottom:8px;border-bottom:1px solid var(--line-2)}
.qcard .qh .qi{width:40px;height:40px;border-radius:11px;background:var(--teal);color:#fff;display:grid;place-items:center;flex:none}
.qcard .qh .qi .ic{width:20px;height:20px}
.qcard .qh b{display:block;font-family:var(--disp);font-weight:800;color:var(--ink);font-size:1.04rem;line-height:1.2}
.qcard .qh small{font-size:.78rem;color:var(--muted)}
.qcard .qlist{display:grid}
.qcard .ql{display:flex;align-items:center;gap:14px;padding:15px 6px;border-bottom:1px solid var(--line-2);transition:.18s}
.qcard .ql:hover{background:var(--teal-050);border-radius:10px;padding-left:12px;padding-right:12px;border-bottom-color:transparent}
.qcard .ql .qn{width:28px;height:28px;border-radius:50%;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;font-family:var(--disp);font-weight:800;font-size:.8rem;flex:none}
.qcard .ql .qt{flex:1;min-width:0}
.qcard .ql .qt b{display:block;font-family:var(--disp);font-weight:700;color:var(--ink);font-size:.98rem;line-height:1.2}
.qcard .ql .qt small{font-size:.78rem;color:var(--muted)}
.qcard .ql .arw{width:16px;height:16px;color:var(--teal);flex:none;stroke-width:2.6}
.qcard .qfoot{display:flex;align-items:center;gap:12px;margin-top:18px;padding-top:16px;border-top:1px solid var(--line-2)}
.qcard .qfoot .fi{width:36px;height:36px;border-radius:10px;background:var(--gold);color:var(--navy);display:grid;place-items:center;flex:none}
.qcard .qfoot .fi .ic{width:18px;height:18px}
.qcard .qfoot b{display:block;font-family:var(--disp);font-weight:800;color:var(--navy);font-size:1rem;line-height:1.2}
.qcard .qfoot small{font-size:.76rem;color:var(--muted)}
@media(max-width:960px){.phero-in{grid-template-columns:1fr;gap:38px}}
@media(max-width:430px){.qcard{padding:24px 20px 20px}}

/* ============ GENERIC PROSE SECTION ============ */
.prose-sec .wrap{max-width:1000px}
.prose h2{font-size:clamp(1.55rem,3vw,2.15rem);letter-spacing:-.02em}
.prose h3{font-size:1.18rem;margin-top:26px}
.prose p{margin-top:16px;font-size:1.02rem;color:var(--body)}
.prose p:first-of-type{margin-top:18px}
.prose+.prose{margin-top:46px;padding-top:46px;border-top:1px solid var(--line)}

/* ============ FEATURE CARDS ============ */
.fcards{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:start}
.fcards.two{grid-template-columns:repeat(2,1fr)}
.fcards.four{grid-template-columns:repeat(4,1fr)}
.fcard{background:#fff;border:1px solid var(--line);border-radius:20px;padding:32px 28px 28px;position:relative;overflow:hidden;transition:.24s}
.fcard::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,var(--teal),var(--teal-2));transform:scaleX(0);transform-origin:left;transition:.3s}
.fcard:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg);border-color:transparent}
.fcard:hover::before{transform:scaleX(1)}
.fcard .fi{width:56px;height:56px;border-radius:15px;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;margin-bottom:18px;font-family:var(--disp);font-weight:800;font-size:1.02rem}
.fcard h3{font-size:1.16rem;letter-spacing:-.01em}
.fcard p{margin-top:12px;font-size:.95rem;color:var(--body)}
.fcard ul{list-style:none;margin:16px 0 0;padding:0;display:grid;gap:9px}
.fcard ul li{display:flex;gap:10px;font-size:.9rem;color:var(--navy);font-weight:600}
.fcard ul li::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--gold);flex:none;margin-top:8px}
@media(max-width:960px){.fcards,.fcards.four{grid-template-columns:1fr 1fr}}
@media(max-width:640px){.fcards,.fcards.two,.fcards.four{grid-template-columns:1fr}}

/* ============ CHECKLIST ============ */
.checks{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:26px;list-style:none;padding:0}
.checks li{display:flex;gap:12px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:16px 18px;font-size:.95rem;color:var(--body)}
.checks li b{color:var(--navy)}
.checks .ic{width:22px;height:22px;color:#fff;background:var(--teal);border-radius:50%;padding:4px;flex:none;stroke-width:3;margin-top:1px}
@media(max-width:760px){.checks{grid-template-columns:1fr}}

/* ============ SERVICE / LINK CARD GRID ============ */
.scards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.scard{background:#fff;border:1px solid var(--line);border-radius:16px;padding:26px 24px;display:block;transition:.2s}
.scard:hover{border-color:var(--teal);box-shadow:var(--shadow);transform:translateY(-4px)}
.scard .si{width:48px;height:48px;border-radius:12px;background:var(--teal-050);color:var(--teal);display:grid;place-items:center;margin-bottom:15px}
.scard .si .ic{width:24px;height:24px}
.scard h3{font-size:1.06rem;letter-spacing:-.01em}
.scard p{margin-top:8px;font-size:.9rem;color:var(--muted)}
.scard .go{display:inline-flex;align-items:center;gap:8px;margin-top:16px;font-weight:700;font-size:.84rem;color:var(--teal)}
.scard .go .ic{width:15px;height:15px;stroke-width:2.6}
@media(max-width:900px){.scards{grid-template-columns:1fr 1fr}}
@media(max-width:560px){.scards{grid-template-columns:1fr}}

/* ============ PRICING ============ */
.tier{margin-top:52px}
.tier:first-of-type{margin-top:0}
.tier>h2{font-size:clamp(1.5rem,3vw,2.05rem);margin-bottom:8px}
.tier>.tsub{font-size:.95rem;color:var(--muted);margin-bottom:24px}
.pgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:22px;align-items:start}
.pgrid.three{grid-template-columns:repeat(3,1fr)}
.plan{background:#fff;border:1px solid var(--line);border-radius:20px;padding:30px 28px 28px;position:relative;overflow:hidden}
.plan.prem{border-color:var(--teal);box-shadow:var(--shadow)}
.plan.prem::after{content:"Premium";position:absolute;top:18px;right:-34px;transform:rotate(45deg);background:var(--gold);color:var(--navy);font-family:var(--f);font-weight:700;font-size:.7rem;letter-spacing:.08em;text-transform:uppercase;padding:5px 40px}
.plan h3{font-size:1.02rem;letter-spacing:.08em;text-transform:uppercase;color:var(--teal);font-family:var(--f);font-weight:700}
.plan .price{margin-top:10px;font-family:var(--disp);font-weight:800;font-size:2.3rem;color:var(--navy);line-height:1}
.plan .price small{font-family:var(--f);font-size:.86rem;font-weight:600;color:var(--muted);letter-spacing:0}
.plan .pgroup{margin-top:24px}
.plan .pglabel{font-size:.68rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);padding-bottom:9px;border-bottom:1px solid var(--line-2);margin-bottom:13px}
.plan ul{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.plan ul li{display:flex;gap:10px;font-size:.92rem;color:var(--body)}
.plan ul .ic{width:19px;height:19px;color:#fff;background:var(--teal);border-radius:50%;padding:3.5px;flex:none;stroke-width:3.4;margin-top:2px}
.plan .btn{margin-top:26px;width:100%}
@media(max-width:900px){.pgrid,.pgrid.three{grid-template-columns:1fr}}

/* ============ FORM ============ */
.formcard{background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow);padding:38px 36px 34px;max-width:860px;margin:0 auto}
.fgrid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.fld{display:flex;flex-direction:column;gap:7px}
.fld.full{grid-column:1/-1}
.fld label{font-size:.84rem;font-weight:700;color:var(--navy)}
.fld label i{color:var(--teal);font-style:normal}
.fld input,.fld select,.fld textarea{font-family:var(--f);font-size:.95rem;color:var(--ink);background:var(--mist-2);border:1px solid var(--line);border-radius:11px;padding:13px 15px;width:100%}
.fld input:focus,.fld select:focus,.fld textarea:focus{outline:none;border-color:var(--teal);background:#fff}
.fld textarea{min-height:120px;resize:vertical}
.fnote{display:flex;gap:12px;align-items:flex-start;background:var(--mist-2);border:1px solid var(--line);border-radius:14px;padding:16px 18px;margin-top:22px;font-size:.9rem;color:var(--body)}
.fnote input{margin-top:4px;flex:none;width:18px;height:18px;accent-color:var(--teal)}
.fsec{font-family:var(--disp);font-weight:800;color:var(--ink);font-size:1.06rem;margin:28px 0 4px;grid-column:1/-1}
.fsec:first-child{margin-top:0}
@media(max-width:640px){.fgrid{grid-template-columns:1fr}.formcard{padding:28px 22px 26px}}

/* ============ LEGAL ============ */
.legal-body{max-width:860px;margin:0 auto}
.legal-body p{margin-top:15px;font-size:1rem;color:var(--body)}
.legal-body h2{font-size:1.28rem;margin-top:38px}
.legal-body ul{margin-top:14px;padding-left:22px;display:grid;gap:9px}
.legal-body li{font-size:1rem;color:var(--body)}
.legal-body table{width:100%;border-collapse:collapse;margin-top:20px;font-size:.92rem}
.legal-body th,.legal-body td{border:1px solid var(--line);padding:11px 13px;text-align:left;vertical-align:top}
.legal-body th{background:var(--mist);font-family:var(--disp);color:var(--ink)}

/* ============ EMBED / PLACEHOLDER ============ */
.embedwrap{background:#fff;border:1px solid var(--line);border-radius:20px;overflow:hidden;box-shadow:var(--shadow)}
.embedwrap iframe{width:100%;min-height:640px;border:0;display:block}
.embednote{margin-top:14px;font-size:.84rem;color:var(--muted);text-align:center}
.bgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.bcard{background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden}
.bcard .bimg{aspect-ratio:16/10}
.bcard .bbody{padding:22px 24px 24px}
.bcard .btag{font-size:.7rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--teal)}
.bcard h3{font-size:1.06rem;margin-top:8px}
.bcard p{margin-top:9px;font-size:.9rem;color:var(--muted)}
@media(max-width:900px){.bgrid{grid-template-columns:1fr 1fr}}
@media(max-width:560px){.bgrid{grid-template-columns:1fr}}

/* ============ STEPS ============ */
.steps{display:grid;gap:16px;counter-reset:st}
.step{display:flex;gap:20px;background:#fff;border:1px solid var(--line);border-radius:16px;padding:24px 26px}
.step .sn{width:42px;height:42px;border-radius:12px;background:var(--navy);color:#fff;display:grid;place-items:center;font-family:var(--disp);font-weight:800;flex:none}
.step h3{font-size:1.08rem}
.step p{margin-top:9px;font-size:.95rem;color:var(--body)}
@media(max-width:560px){.step{flex-direction:column;gap:14px;padding:22px}}

/* long URLs and unbreakable strings in legal copy */
.legal-body,.legal-body p,.legal-body li,.legal-body td{overflow-wrap:anywhere;word-break:break-word}
.prose p,.fcard p,.rc p,.tc blockquote,.faq .fa{overflow-wrap:anywhere}

/* ============ MULTI-COLUMN SERVICES DROPDOWN ============ */
.dropdown.wide{min-width:660px;padding:14px;display:grid;grid-template-columns:repeat(3,minmax(196px,1fr));gap:2px 8px}
.dropdown .dhd{display:block;font-family:var(--f);font-size:.64rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);padding:9px 13px 5px}
.dropdown.wide a{padding:9px 13px;font-size:.84rem}
@media(max-width:1360px){
  .dropdown.wide{display:block;min-width:0;padding:0;grid-template-columns:1fr}
  .dropdown.wide a{padding:14px 34px;font-size:.94rem}
  .dropdown .dhd{padding:14px 26px 6px;background:var(--mist)}
  .drop-cb:checked ~ .dropdown{max-height:1400px}
}
@media(min-width:1361px){
  .nav-links>li>a{padding:9px 8px;font-size:.8rem}
  .nav{gap:14px}
}

/* ============ FIVE-COLUMN FOOTER ============ */
.foot-top{grid-template-columns:1.5fr repeat(4,1fr);gap:30px}
@media(max-width:1180px){.foot-top{grid-template-columns:repeat(3,1fr);gap:32px}.foot-brand{grid-column:1/-1}}
@media(max-width:760px){.foot-top{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.foot-top{grid-template-columns:1fr}}
